#include <bits/stdc++.h>
using namespace std;

using ll = long long;
constexpr ll MOD = 1000000007LL;

ll modPow(ll base, int exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> ad(k + 1, 0);
    ll previousPower = 0;
    ll prefix = 0;
    ll answer = 0;

    for (int i = 1; i <= k; ++i) {
        ll currentPower = modPow(i, n);

        ad[i] = (ad[i] + currentPower - previousPower) % MOD;
        if (ad[i] < 0) ad[i] += MOD;
        previousPower = currentPower;

        prefix += ad[i];
        if (prefix >= MOD) prefix -= MOD;

        answer = (answer + (prefix ^ static_cast<ll>(i))) % MOD;

        for (int multiple = i + i; multiple <= k; multiple += i) {
            ad[multiple] -= ad[i];
            if (ad[multiple] < 0) ad[multiple] += MOD;
        }
    }

    cout << answer;
    return 0;
}

