#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

ll modPow(ll x, int y) {
    ll result = 1;
    while (y) {
        if (y & 1) result = result * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<ll> divisorSum(k + 1, 0);

    ll answer = 0;
    ll prefix = 0;
    ll previousPower = 0;

    for (int i = 1; i <= k; ++i) {
        ll currentPower = modPow(i, n);
        ll current = (currentPower - previousPower - divisorSum[i]) % MOD;
        if (current < 0) current += MOD;

        prefix += current;
        if (prefix >= MOD) prefix -= MOD;

        answer += (prefix ^ i);
        answer %= MOD;

        for (int multiple = i + i; multiple <= k; multiple += i) {
            divisorSum[multiple] += current;
            if (divisorSum[multiple] >= MOD) {
                divisorSum[multiple] -= MOD;
            }
        }

        previousPower = currentPower;
    }

    cout << answer;
    return 0;
}

