ll modPow(ll x, int y) {
    ll result = 1;
    while (y > 0) {
        if (y & 1) result = result * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<ll> ad(k + 1);
    ad[1] = 1;

    ll previous = modPow(1, n);
    for (int i = 2; i <= k; ++i) {
        ll current = modPow(i, n);
        ad[i] = (current - previous + MOD) % MOD;
        previous = current;
    }

    ll dp = 0;
    ll answer = 0;

    for (int i = 1; i <= k; ++i) {
        dp += ad[i];
        if (dp >= MOD) dp -= MOD;

        answer += (dp ^ static_cast<ll>(i));
        if (answer >= MOD) answer -= MOD;

        for (int multiple = i + i; multiple <= k; multiple += i) {
            ad[multiple] -= ad[i];
            if (ad[multiple] < 0) ad[multiple] += MOD;
        }
    }

    cout << answer;
    return 0;
}

